#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 1 : socle back-end, sans écran ni e-mail.
#  Schéma + migration 20261120000000_tickets :
#   - TicketCategory (gestion → admin@, groupe Administrateurs ; support → support@, groupe Support)
#   - Ticket (numéro AKFC-0042, statut, responsable, échéance de 1re réponse), TicketMessage, TicketEvent
#   - SiteSettings.ticketResponseDays (7 j par défaut)
#  Code : packages/backend/src/modules/tickets/ (ticketRef, ensureTicketCategories, tickets.service)
#         + catégories garanties au démarrage (instrumentation).
#  Preuves avant commit (sinon TOUT est restauré) : prisma validate, generate, pnpm check,
#  puis sur la base LOCALE : migrate deploy + migrate diff VIDE.
# Usage : bash apply-tickets-increment1.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
S="prisma/schema.prisma"
grep -q "INSTRUCTOR_BIO" "$S" || { echo "ERREUR: applique d'abord apply-naming-and-bio-media.sh." >&2; exit 1; }
grep -q "^model Ticket " "$S" && { echo "— déjà appliqué"; exit 0; }

MIG="prisma/migrations/20261120000000_tickets"
MOD="packages/backend/src/modules/tickets"
INS="apps/web/src/instrumentation.ts"
FILES=("$S" "$INS")
BK=/tmp/akfc_tk_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do [ -f "$f" ] || { echo "ERREUR: $f introuvable." >&2; exit 1; }; mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
[ -e "$MIG" ] && { echo "ERREUR: $MIG existe déjà." >&2; exit 1; }
[ -e "$MOD" ] && { echo "ERREUR: $MOD existe déjà." >&2; exit 1; }
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -rf "$MIG" "$MOD"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_tk; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/schema_edit.py"
echo '' | base64 -d > "$W/code_edit.py"
echo '' | base64 -d > "$W/migration.sql"
echo '' | base64 -d > /tmp/akfc_tk_rollback.sql
echo '' | base64 -d > "$W/ticketRef.ts"
echo '' | base64 -d > "$W/ensureTicketCategories.service.ts"
echo '' | base64 -d > "$W/tickets.service.ts"

echo "== application =="
python3 "$W/schema_edit.py" "$S" || { restore; exit 1; }
mkdir -p "$MIG" && cp "$W/migration.sql" "$MIG/migration.sql" && echo "  ok  migration $MIG"
mkdir -p "$MOD" && cp "$W"/ticketRef.ts "$W"/ensureTicketCategories.service.ts "$W"/tickets.service.ts "$MOD/" && echo "  ok  module $MOD (3 fichiers)"
python3 "$W/code_edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

PRISMA(){ pnpm exec prisma "$@" 2>/dev/null || pnpm --filter @workspace/backend exec prisma "$@"; }
echo "== prisma validate / generate =="
PRISMA validate --schema "$S" > /tmp/akfc_v.log 2>&1 || { tail -8 /tmp/akfc_v.log; restore; exit 1; }
PRISMA generate > /tmp/akfc_g.log 2>&1 || { tail -8 /tmp/akfc_g.log; restore; exit 1; }
echo "  ✅ schéma valide, client généré"
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

echo "== base LOCALE : migrate deploy + migrate diff (doit être VIDE) =="
DBURL=$(grep -E '^DATABASE_URL=' .env 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)
HOST=$(python3 -c "import sys;from urllib.parse import urlparse;print(urlparse(sys.argv[1]).hostname or '')" "$DBURL" 2>/dev/null || true)
case "$HOST" in
  localhost|127.0.0.1|::1) echo "  base : $HOST (locale)";;
  *) echo "❌ DATABASE_URL (.env) ne pointe pas vers une base LOCALE (hôte « $HOST »). Par sécurité, rien n'est migré."; restore; exit 1;;
esac
if ! PRISMA migrate deploy > /tmp/akfc_md.log 2>&1; then
  echo "❌ migrate deploy a échoué :"; tail -12 /tmp/akfc_md.log
  echo "   Si la migration est marquée en échec : psql \"<DATABASE_URL>\" -f /tmp/akfc_tk_rollback.sql"
  restore; exit 1
fi
set +e
PRISMA migrate diff --from-url "$DBURL" --to-schema-datamodel "$S" --exit-code > /tmp/akfc_d.log 2>&1
code=$?; set -e
case $code in
  0) echo "  ✅ base migrée = schéma (aucune dérive)";;
  *) echo "❌ la base migrée ne correspond pas au schéma (code $code) :"; head -20 /tmp/akfc_d.log
     echo "   Annuler la migration sur la base LOCALE : psql \"<DATABASE_URL>\" -f /tmp/akfc_tk_rollback.sql"
     restore; exit 1;;
esac

git add "$S" "$INS" "$MIG" "$MOD"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): socle des demandes (catégories, numéros, échéance, historique)

